from pathlib import Path
out=Path(__file__).resolve().parents[1]/'tests/fixtures/scenarios';out.mkdir(parents=True,exist_ok=True)
base='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>IXR deterministic fixture: {title}</title><style>
*{{box-sizing:border-box}}body{{margin:0;background:#eef3fb;color:#172849;font:15px/1.55 system-ui,sans-serif}}main{{padding:32px;max-width:1080px;margin:auto}}h1{{font-size:28px;letter-spacing:-.5px}}.paper{{background:white;padding:24px;border-radius:14px;border:1px solid #d9e4ef;margin-bottom:16px}}.top{{position:sticky;top:0;background:#24365a;color:white;padding:12px 32px;z-index:4}}button{{border:0;border-radius:7px;padding:10px 15px;background:#5175d8;color:white}}
{css}</style></head><body><header class="top">Interface X-Ray regression suite · {title}</header><main><h1>{title}</h1><div class="paper">{html}</div></main>{script}</body></html>'''
cases={
'article': ('<article><h2>Content & typography</h2><p>Readable article text, with long paragraphs and ordinary document flow.</p><p>CSS layout engines should produce predictable measurements.</p></article>','', ''),
'flex': ('<div id="flex-parent"><div id="flex-child">A flex item with min-width larger than its parent</div></div>', '#flex-parent{display:flex;width:270px;gap:12px;padding:5px;border:2px solid purple}#flex-child{min-width:500px;padding:18px;background:#efc0de;white-space:nowrap}', ''),
'grid': ('<div id="grid-parent"><div class="gitem">A</div><div class="gitem">B</div><div class="gitem">C</div><div class="gitem">D</div></div>', '#grid-parent{display:grid;grid-template-columns:repeat(2,1fr);gap:15px;max-width:570px}.gitem{padding:45px;background:#d7e2f6;border:1px solid #acc2ed}', ''),
'nested-scroll': ('<div class="scroll"><div><h2>Long scrollable container</h2>'+''.join(f'<p>Scrollable nested element row {i} · line and geometry</p>' for i in range(40))+'</div></div>', '.scroll{height:260px;overflow:auto;padding:15px;border:2px solid #6381c4}.scroll>div{width:100%}', ''),
'overflow': ('<div id="over">This element goes beyond the viewport</div>','#over{width:calc(100vw + 95px);height:80px;background:#f4c5b4;padding:20px;outline:2px solid #d46a55}', ''),
'clip': ('<div id="clip-parent"><div id="clip-child">Clipped by parent · large child</div></div>', '#clip-parent{width:230px;height:80px;overflow:hidden;border:2px solid #b9a6ee}#clip-child{width:410px;height:130px;background:#e8ccee;padding:15px}', ''),
'fixed-overlay': ('<p>Heading, navigation and fixed element can overlap.</p><div id="banner">Fixed overlay covers this portion of the document.</div>', '#banner{position:fixed;left:0;top:0;width:100vw;height:115px;background:#c28ef0bd;z-index:99;padding:20px}', ''),
'large-dom': ('<div id="many">'+''.join(f'<span class="cell">{i}</span>' for i in range(5400))+'</div>', '#many{display:grid;grid-template-columns:repeat(30,1fr);gap:1px}.cell{font-size:9px;line-height:11px;height:11px;background:#e5ecf8;overflow:hidden}', ''),
'dynamic-spa': ('<button id="append">Append SPA node</button><section id="reactive"><div id="initial">Initial node</div></section>', '.dynamic{border:1px solid #92b9e0;padding:10px;margin-top:4px}', '<script>let i=0;document.querySelector("#append").onclick=()=>document.querySelector("#reactive").insertAdjacentHTML("beforeend",`<div class="dynamic">Reactive node ${++i}</div>`);</script>'),
'mobile': ('<div id="responsive"><div>Responsive panel 1</div><div>Responsive panel 2</div></div>', '#responsive{display:grid;grid-template-columns:1fr 1fr;gap:10px}#responsive>div{padding:22px;border-radius:8px;background:#c9d7f8}@media(max-width:600px){#responsive{grid-template-columns:1fr}}', ''),
'floating-overlap': ('<div id="overlap-root"><div id="float-a">First overlay</div><div id="float-b">Second overlay</div></div>', '#overlap-root{position:relative;height:170px}#float-a,#float-b{position:absolute;width:240px;height:110px;padding:12px}#float-a{left:20px;top:20px;background:#ade1ee}#float-b{left:70px;top:40px;background:#deafe3}', ''),
'small-control': ('<button id="small-button">+</button>', '#small-button{width:10px;height:10px;padding:0;font-size:9px}', ''),
'shadow-transform': ('<div id="rotated">Transformed region</div><div id="shadow-host"></div>', '#rotated{width:270px;padding:20px;background:#edccef;transform:rotate(4deg) translateX(12px)}', '<script>const h=document.querySelector("#shadow-host"),s=h.attachShadow({mode:"open"});s.innerHTML=`<style>.shadow-child{padding:18px;border:2px solid #608de9;background:#edf3ff}</style><div class="shadow-child"><button id="inside">Open Shadow DOM content</button></div>`;</script>')
}
for name,(html,css,script) in cases.items(): (out/f'{name}.html').write_text(base.format(title=name.replace('-',' ').title(),html=html,css=css,script=script),encoding='utf-8')
print('generated',len(cases),'fixtures in',out)
